import java.util.*;
import java.io.*;

public class Main {
    // SimpleEdge class (unweighted)
    static class SimpleEdge {
        int trg;
        SimpleEdge(int trg) { this.trg = trg; }
    }

    // MCMFEdge class for min-cost max-flow
    static class MCMFEdge {
        int trg;
        int cost;
        int adjcost;
        int flow;
        int cap;
        int dual; // index of reverse edge in target's adjacency list

        MCMFEdge(int trg, int cost, int cap, int dual) {
            this.trg = trg;
            this.cost = cost;
            this.adjcost = cost;
            this.flow = 0;
            this.cap = cap;
            this.dual = dual;
        }

        MCMFEdge() {} // for filling
    }

    // MCMFGraph (only for int flow type)
    static class MCMFGraph {
        int size;
        ArrayList<ArrayList<MCMFEdge>> nodes;

        MCMFGraph(int size) {
            this.size = size;
            nodes = new ArrayList<>(size);
            for (int i = 0; i < size; i++) {
                nodes.add(new ArrayList<>());
            }
        }

        int size() { return size; }
        int size(int id) { return nodes.get(id).size(); }
        ArrayList<MCMFEdge> edges(int id) { return nodes.get(id); }

        // Add edge with capacity cap and reverse capacity rcap
        // For simplicity, we only handle the case where rcap==0 (typical usage in main)
        void add(int a, int b, int cost, int cap, int rcap) {
            if (a == b) return;
            // In main, cap>0 and rcap==0 always, so we directly add edges.
            // But keep general: if both >0, add two separate edges with same cost.
            if (cap > 0 && rcap > 0) {
                add(a, b, cost, cap, 0);
                add(b, a, cost, rcap, 0);
                return;
            } else if (rcap > 0) {
                // swap and add single edge? Not used in main.
                add(b, a, cost, rcap, 0);
                return;
            }
            int da = nodes.get(a).size();
            int db = nodes.get(b).size();
            nodes.get(a).add(new MCMFEdge(b, cost, cap, db));
            nodes.get(b).add(new MCMFEdge(a, -cost, 0, da));
        }

        // Augment flow along shortest path
        int[] augment(int source, int sink) {
            int N = size();
            int INF = Integer.MAX_VALUE / 2;
            int[] upby = new int[N];
            long[] prio = new long[N]; // use long to avoid overflow
            int[] preve = new int[N];
            boolean[] visited = new boolean[N];

            Arrays.fill(prio, Long.MAX_VALUE);
            prio[source] = 0;
            upby[source] = Integer.MAX_VALUE; // effectively infinite
            PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[1]));
            pq.add(new int[]{source, 0});

            while (!pq.isEmpty()) {
                int[] cur = pq.poll();
                int v = cur[0];
                long p = cur[1];
                if (p != prio[v]) continue;
                for (int i = 0; i < size(v); i++) {
                    MCMFEdge e = nodes.get(v).get(i);
                    if (e.flow < e.cap && e.adjcost >= 0) {
                        long p2 = p + e.adjcost;
                        if (p2 < prio[e.trg]) {
                            prio[e.trg] = p2;
                            preve[e.trg] = e.dual; // index of reverse edge in e.trg's list
                            upby[e.trg] = Math.min(e.cap - e.flow, upby[v]);
                            pq.add(new int[]{e.trg, (int)p2});
                        }
                    }
                }
            }

            int up = upby[sink];
            long upcost = 0;
            if (up > 0) {
                int cur = sink;
                while (cur != source) {
                    MCMFEdge ed = nodes.get(cur).get(preve[cur]);
                    MCMFEdge e = nodes.get(ed.trg).get(ed.dual);
                    e.flow += up;
                    upcost += (long) e.cost * up;
                    ed.flow -= up;
                    cur = ed.trg;
                }

                // Update potentials
                for (int i = 0; i < N; i++) {
                    for (int j = 0; j < size(i); j++) {
                        MCMFEdge e = nodes.get(i).get(j);
                        // prio values are within int range (since costs are ints)
                        e.adjcost += (int)(prio[i] - prio[e.trg]);
                    }
                }
            }
            return new int[]{up, (int)upcost}; // return int, but upcost might overflow? Use long in make_flow
        }

        // Returns total flow and total cost
        long[] makeFlow(int source, int sink) {
            for (int i = 0; i < size(); i++) {
                for (int j = 0; j < size(i); j++) {
                    MCMFEdge e = nodes.get(i).get(j);
                    e.flow = 0;
                    e.adjcost = e.cost;
                }
            }

            long flow = 0;
            long cost = 0;
            int[] res;
            while ((res = augment(source, sink))[0] != 0) {
                flow += res[0];
                cost += res[1];
            }
            return new long[]{flow, cost};
        }
    }

    // Main
    public static void main(String[] args) throws Exception {
        // Redirect input/output if arguments given
        if (args.length > 0) {
            System.setIn(new FileInputStream(args[0]));
            if (args.length > 1) {
                System.setOut(new PrintStream(new FileOutputStream(args[1])));
            }
        }

        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int K = sc.nextInt();
        int C = sc.nextInt();
        int D = sc.nextInt();

        int[] a = new int[K];
        int[] starts = new int[N]; // number of people starting at each node
        for (int i = 0; i < K; i++) {
            a[i] = sc.nextInt() - 1; // 0-indexed
            starts[a[i]]++;
        }

        int maxT = K + N + 1;
        int V = (maxT + 1) * N + 2;
        int src = V - 2;
        int sink = V - 1;
        MCMFGraph g = new MCMFGraph(V);

        // Source to start nodes
        for (int i = 0; i < N; i++) {
            if (starts[i] > 0) {
                g.add(src, i, 0, starts[i], 0);
            }
        }

        // Connect each node at time t to sink (only at t = 0? Wait: original connects all t)
        for (int t = 0; t <= maxT; t++) {
            g.add(t * N, sink, 0, K, 0);
        }

        // Waiting edges (same node, time t -> t+1)
        for (int i = 0; i < N; i++) {
            for (int t = 0; t < maxT; t++) {
                g.add(t * N + i, (t + 1) * N + i, C, K, 0);
            }
        }

        // Road edges
        for (int i = 0; i < M; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            for (int t = 0; t < maxT; t++) {
                for (int j = 0; j < K; j++) {
                    int cost = C + (2 * j + 1) * D;
                    g.add(t * N + u, (t + 1) * N + v, cost, 1, 0);
                    g.add(t * N + v, (t + 1) * N + u, cost, 1, 0);
                }
            }
        }

        long[] flowCost = g.makeFlow(src, sink);
        // Assert flow == K
        if (flowCost[0] != K) {
            // Should not happen; but just in case
            System.out.println("Error: flow mismatch");
        }
        System.out.println(flowCost[1]);
    }
}
